set-var "lrn-id" get-val-public "itemId"
learnosity items [
  item questions [
    bowtie stimulus "A 68-year-old post-operative patient has a temperature of 38.9°C, heart rate 118 beats/minute, blood pressure 88/52 mm Hg, and rising lactate. Select the two priority actions, the condition the patient is most likely experiencing, and the two parameters to monitor."
      column-titles [
        "Priority Actions"
        "Condition Most Likely"
        "Parameters to Monitor"
      ] possible-responses [
      [
        "Obtain blood cultures"
        "Administer the prescribed fluid bolus"
        "Encourage ambulation"
        "Administer a sedative"
      ]
      [
        "Sepsis"
        "Pulmonary embolism"
        "Hypoglycemia"
      ]
      [
        "Serum lactate"
        "Mean arterial pressure"
        "Visual acuity"
        "Bowel sounds"
      ]
    ] valid-response [
      [
        "Obtain blood cultures"
        "Administer the prescribed fluid bolus"
      ]
      [
        "Sepsis"
      ]
      [
        "Serum lactate"
        "Mean arterial pressure"
      ]
    ] {}
  ] {}
] {}..

