set-var "lrn-id" get-val-public "itemId"
learnosity items [
  item metadata [
    tags {
      "Common Core": "HS-LS1-7"
      DOK: 2
      Difficulty: "medium"
    }
  ] questions [
    mcq stimulus "Which organelle is the site of aerobic respiration?"
      options [
        "Mitochondrion"
        "Ribosome"
        "Golgi apparatus"
        "Nucleus"
      ] valid-response [
      0
    ] metadata [
      distractor-rationale [
        "Correct — the mitochondrion is the site of aerobic respiration and ATP production."
        "Confuses aerobic respiration with protein synthesis, which occurs at the ribosome."
        "Confuses aerobic respiration with the Golgi apparatus's role in packaging and shipping proteins."
        "Confuses aerobic respiration with the nucleus's role in storing genetic material."
      ]
    ] {}
  ] {}
] {}..

